<?php
if(!defined('ABSPATH'))exit;
function dgs_student_delete_allowed($id){$u=get_userdata($id);return current_user_can('dgs_manage_education')&&!is_multisite()&&$u&&(int)$id!==get_current_user_id()&&count($u->roles)===1&&in_array('dgs_student',$u->roles,true);}
function dgs_student_delete_tables(){$e=dgs_edu_tables();$a=dgs_att_tables();$q=dgs_quiz_tables();$s=dgs_study_tables();$h=dgs_hw_tables();$m=dgs_mg_tables();$c=dgs_cm_tables();return array(dgs_membership_table(),$e['enrollments'],$e['counseling'],$a['records'],$q['attempts'],$s['entries'],$s['days'],$s['feedback'],$h['submissions'],$m['entries'],dgs_grade_table(),dgs_rc_feedback_table(),$c['items']);}
function dgs_student_delete($id,$confirm,$approved){
 $id=absint($id);if(!dgs_student_delete_allowed($id))return dgs_edu_error('access','حذف این حساب مجاز نیست.');$u=get_userdata($id);if($approved!=='1'||!is_string($confirm)||trim($confirm)!==$u->display_name)return dgs_edu_error('confirm','نام کامل دانش‌آموز و تأیید حذف دائمی لازم است.');
 $lock='dgs_student_delete_'.$id;if(!add_option($lock,time(),'','no'))return dgs_edu_error('busy','حذف در حال انجام است؛ صفحه را تازه کنید.');global $wpdb;$f=dgs_fin_tables();$h=dgs_hw_tables();$m=dgs_mg_tables();$files=array();$moved=array();$committed=false;
 try{
  foreach(get_user_meta($id,'_dgs_record_document',false) as $doc)if(is_array($doc)&&isset($doc['stored_file']))$files[]=$doc['stored_file'];foreach($wpdb->get_col($wpdb->prepare("SELECT stored_file FROM {$h['submissions']} WHERE student_id=%d",$id)) as $file)$files[]=$file;
  // Only private files exclusively referenced by this student are removed.
  foreach(array_unique($files) as $file){if(!is_string($file)||!preg_match('/^[a-f0-9]{32}\.(pdf|png|jpe?g|docx|xlsx|pptx)$/D',$file))continue;$shared=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$h['submissions']} WHERE student_id<>%d AND stored_file=%s",$id,$file));$others=$wpdb->get_col($wpdb->prepare("SELECT meta_value FROM {$wpdb->usermeta} WHERE user_id<>%d AND meta_key='_dgs_record_document' AND meta_value LIKE %s",$id,'%'.$wpdb->esc_like($file).'%'));if($shared||$others)continue;$path=dgs_hw_dir().'/'.$file;if(!is_file($path))continue;$temp=dgs_hw_dir().'/deleted-'.wp_generate_password(24,false,false).'.tmp';if(!@rename($path,$temp))throw new RuntimeException('آماده‌سازی حذف فایل خصوصی انجام نشد؛ هیچ حسابی حذف نشد.');$moved[$path]=$temp;}
  if($wpdb->query('START TRANSACTION')===false)throw new RuntimeException('شروع حذف انجام نشد.');
  $run=function($sql){global $wpdb;if($wpdb->query($sql)===false)throw new RuntimeException('حذف سوابق کامل نشد؛ عملیات برگشت داده شد.');};
  foreach(array('payments','installments') as $key)$run($wpdb->prepare("DELETE FROM {$f[$key]} WHERE account_id IN (SELECT id FROM {$f['accounts']} WHERE student_id=%d)",$id));$run($wpdb->prepare("DELETE FROM {$f['accounts']} WHERE student_id=%d",$id));
  $run($wpdb->prepare("DELETE FROM {$m['audit']} WHERE entry_id IN (SELECT id FROM {$m['entries']} WHERE student_id=%d)",$id));
  // Legacy audit snapshots can refer to a student/user without a mark-entry ID.
  $last=0;do{$rows=$wpdb->get_results($wpdb->prepare("SELECT id,before_data,after_data FROM {$m['audit']} WHERE id>%d ORDER BY id LIMIT 300",$last));foreach($rows as $row){$last=(int)$row->id;$scrub=function($value)use(&$scrub,$id){if(!is_array($value))return $value;foreach(array('student_id','user_id') as $key)if(isset($value[$key])&&is_scalar($value[$key])&&(int)$value[$key]===$id)return null;foreach($value as $key=>$item)if(is_array($item)){$clean=$scrub($item);if($clean===null)unset($value[$key]);else $value[$key]=$clean;}return $value;};$before=json_decode($row->before_data,true);$after=json_decode($row->after_data,true);$cleanBefore=$scrub($before);$cleanAfter=$scrub($after);if($cleanBefore!==$before||$cleanAfter!==$after){if($cleanBefore===null&&$cleanAfter===null)$run($wpdb->prepare("DELETE FROM {$m['audit']} WHERE id=%d",$row->id));else $run($wpdb->prepare("UPDATE {$m['audit']} SET before_data=%s,after_data=%s WHERE id=%d",wp_json_encode($cleanBefore),wp_json_encode($cleanAfter),$row->id));}}}while(count($rows)===300);
  foreach(dgs_student_delete_tables() as $table)$run($wpdb->prepare("DELETE FROM $table WHERE student_id=%d",$id));
  foreach(get_comments(array('user_id'=>$id,'status'=>'all','fields'=>'ids','number'=>0)) as $comment)if(!wp_delete_comment($comment,true))throw new RuntimeException('حذف دیدگاه حساب انجام نشد.');
  require_once ABSPATH.'wp-admin/includes/user.php';if(!wp_delete_user($id))throw new RuntimeException('حساب حذف نشد؛ عملیات برگشت داده شد.');
  if($wpdb->query('COMMIT')===false)throw new RuntimeException('ثبت نهایی حذف انجام نشد.');$committed=true;clean_user_cache($u);wp_cache_delete($id,'user_meta');
  foreach($moved as $temp)if(!@unlink($temp)){$pending=get_option('dgs_student_delete_files',array());$pending[]=basename($temp);update_option('dgs_student_delete_files',$pending,false);}
  return true;
 }catch(Throwable $error){if(!$committed)$wpdb->query('ROLLBACK');foreach($moved as $path=>$temp)if(is_file($temp))@rename($temp,$path);clean_user_cache($u);wp_cache_delete($id,'user_meta');return dgs_edu_error('delete',$error->getMessage());}finally{delete_option($lock);}
}
add_action('init',function(){$pending=get_option('dgs_student_delete_files',array());if(!$pending)return;$left=array();foreach($pending as $file)if(is_string($file)&&preg_match('/^deleted-[A-Za-z0-9]{24}\.tmp$/D',$file)){$path=dgs_hw_dir().'/'.$file;if(is_file($path)&&!@unlink($path))$left[]=$file;}if($left)update_option('dgs_student_delete_files',$left,false);else delete_option('dgs_student_delete_files');},99);
function dgs_student_delete_ui($id){if(!dgs_student_delete_allowed($id))return '';$u=get_userdata($id);return '<button type="button" class="dg-btn dg-btn-outline" style="color:#b42332;border-color:#e6a3aa" data-school-dialog="dsr-delete-student">حذف با تمام سوابق</button><dialog id="dsr-delete-student" class="dsp-dialog"><button type="button" class="dsp-dialog-close" data-school-close>×</button><h3>حذف دائمی '.esc_html($u->display_name).'</h3><p>حساب، پرونده، انتساب کلاس، نمرات، حضور و غیاب، آزمون‌ها، تکالیف، مطالعه، مشاوره، مالی، پیامک‌ها و مدارک خصوصی این دانش‌آموز در همه سال‌ها حذف می‌شوند. این عملیات قابل بازگشت نیست.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="dge-form">'.wp_nonce_field('dgs_delete_student_'.$id,'delete_nonce',true,false).'<input type="hidden" name="action" value="dgs_delete_student"><input type="hidden" name="student_id" value="'.$id.'"><label>برای تأیید، نام کامل «'.esc_html($u->display_name).'» را بنویسید<input name="confirm_name" autocomplete="off" required></label><label class="dsp-checkbox"><input name="approve" type="checkbox" value="1" required>حذف دائمی حساب و سوابق همه سال‌ها را تأیید می‌کنم.</label><button class="dg-btn" style="background:#b42332;color:white">حذف دائمی دانش‌آموز و تمام سوابق</button></form></dialog>';}
add_action('admin_post_dgs_delete_student',function(){if(($_SERVER['REQUEST_METHOD']??'')!=='POST')wp_die('روش مجاز نیست.','',array('response'=>405));$id=isset($_POST['student_id'])&&is_scalar($_POST['student_id'])?absint($_POST['student_id']):0;if(!dgs_student_delete_allowed($id))wp_die('دسترسی ندارید.','',array('response'=>403));check_admin_referer('dgs_delete_student_'.$id,'delete_nonce');$name=isset($_POST['confirm_name'])&&is_string($_POST['confirm_name'])?wp_unslash($_POST['confirm_name']):'';$approve=isset($_POST['approve'])&&is_string($_POST['approve'])?$_POST['approve']:'';$r=dgs_student_delete($id,$name,$approve);$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($r),'text'=>is_wp_error($r)?$r->get_error_message():'دانش‌آموز و سوابق مرتبط همه سال‌ها حذف شدند.'),300);wp_safe_redirect(add_query_arg('dg_notice',$token,dgs_edu_url('education',dgs_edu_current_year())),303);exit;});
